<?php
foreach([192,512] as $size){$im=imagecreatetruecolor($size,$size);$green=imagecolorallocate($im,23,77,60);$cream=imagecolorallocate($im,247,244,230);$gold=imagecolorallocate($im,232,199,149);imagefill($im,0,0,$green);$thickness=(int)($size*.12);imagesetthickness($im,$thickness);imagearc($im,(int)($size*.5),(int)($size*.39),(int)($size*.38),(int)($size*.29),80,310,$cream);imagearc($im,(int)($size*.5),(int)($size*.62),(int)($size*.38),(int)($size*.29),260,130,$cream);imagefilledellipse($im,(int)($size*.75),(int)($size*.24),(int)($size*.12),(int)($size*.12),$gold);imagepng($im,__DIR__.'/../public/assets/icon-'.$size.'.png');imagedestroy($im);}
